    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        System.out.println("output  " + outputPath);
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // Read task events from the gzipped CSV source (or a test-injected source).
        SingleOutputStreamOperator<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .returns(TaskEvent.class)
                .name("task-events");

        // Keep only SUBMIT events; each one represents a task placed in the queue.
        SingleOutputStreamOperator<TaskEvent> submits = tasks
                .filter(te -> te.eventType == TaskEvent.SUBMIT)
                .name("filter-submit")
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                                .withTimestampAssigner((e, ts) -> e.timestamp / 1000L));

        // Session-window per job on event time: one window per stage.
        // Count the SUBMIT events in each session. Resubmits after FAIL/EVICT are
        // counted separately because they are independent SUBMIT events.
        SingleOutputStreamOperator<Tuple2<Long, Long>> perSession = submits
                .map(new ToJobCount())
                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {}))
                .keyBy(t -> t.f0)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .sum(1)
                .name("session-count");

        // Per job, keep the largest session count in keyed state and emit a
        // single record on the final watermark (end-of-stream). This matches
        // "once the job has finished" and avoids intermediate updates that
        // keyBy().maxBy() would produce in STREAMING mode.
        SingleOutputStreamOperator<Tuple2<Long, Long>> maxPerJob = perSession
                .keyBy(t -> t.f0)
                .process(new LongestSessionFunction())
                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {}))
                .name("longest-session");

        // Format and write results. Use the injected test sink if one is set,
        // otherwise write one line per tuple to the configured output file.
        SingleOutputStreamOperator<String> formatted = maxPerJob
                .map((MapFunction<Tuple2<Long, Long>, String>)
                        t -> "(" + t.f0 + "," + t.f1 + ")")
                .returns(String.class)
                .name("format");

        @SuppressWarnings("unchecked")
        SinkFunction<String> testSink = (SinkFunction<String>) out;
        if (testSink != null) {
            formatted.addSink(testSink).name("test-sink");
        } else {
            if (outputPath == null) {
                throw new IllegalArgumentException("--output path must be provided");
            }
            formatted.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                    .setParallelism(1)
                    .name("file-sink");
        }

        env.execute("LongestSessionPerJob");
    }

    /** Map a SUBMIT task event to a (jobId, 1) pair for counting. */
    public static final class ToJobCount
            implements MapFunction<TaskEvent, Tuple2<Long, Long>> {
        private static final long serialVersionUID = 1L;

        @Override
        public Tuple2<Long, Long> map(TaskEvent te) {
            return Tuple2.of(te.jobId, 1L);
        }
    }

    /**
     * Maintain the largest session count seen for each job and emit a single
     * (jobId, maxCount) record when the final event-time watermark arrives.
     */
    public static final class LongestSessionFunction
            extends KeyedProcessFunction<Long, Tuple2<Long, Long>, Tuple2<Long, Long>> {

        private static final long serialVersionUID = 1L;
        private static final long FINAL_TIMER = Long.MAX_VALUE - 1L;

        private transient ValueState<Long> maxCount;
        private transient ValueState<Boolean> timerArmed;

        @Override
        public void open(Configuration parameters) {
            maxCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxCount", Long.class));
            timerArmed = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("timerArmed", Boolean.class));
        }

        @Override
        public void processElement(Tuple2<Long, Long> value,
                                   Context ctx,
                                   Collector<Tuple2<Long, Long>> out) throws Exception {
            Long current = maxCount.value();
            if (current == null || value.f1 > current) {
                maxCount.update(value.f1);
            }
            Boolean armed = timerArmed.value();
            if (armed == null || !armed) {
                ctx.timerService().registerEventTimeTimer(FINAL_TIMER);
                timerArmed.update(true);
            }
        }

        @Override
        public void onTimer(long timestamp,
                            OnTimerContext ctx,
                            Collector<Tuple2<Long, Long>> out) throws Exception {
            Long m = maxCount.value();
            if (m != null) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), m));
            }
        }
    }
